CREATE TABLE IF NOT EXISTS webserver_site (
    id              BIGINT       NOT NULL,
    uuid            VARCHAR(64)  NOT NULL,
    tenant_id       BIGINT       NOT NULL DEFAULT 0,
    organization_id BIGINT       NOT NULL DEFAULT 0,
    data_scope      INTEGER      NOT NULL DEFAULT 1,
    user_id         BIGINT,
    name            VARCHAR(100) NOT NULL,
    slug            VARCHAR(100) NOT NULL,
    description     VARCHAR(500),
    application_type VARCHAR(16) NOT NULL DEFAULT 'WEB',
    site_type       INTEGER      NOT NULL DEFAULT 1,
    status          INTEGER      NOT NULL DEFAULT 0,
    runtime_config  JSONB        NOT NULL DEFAULT '{}',
    metadata        JSONB        NOT NULL DEFAULT '{}',
    created_at      TIMESTAMPTZ  NOT NULL,
    updated_at      TIMESTAMPTZ  NOT NULL,
    version         BIGINT       NOT NULL DEFAULT 0,
    deleted_at      TIMESTAMPTZ,
    deleted_by      BIGINT,
    PRIMARY KEY (id),
    CONSTRAINT uk_webserver_site_uuid UNIQUE (uuid),
    CONSTRAINT uk_webserver_site_tenant_id UNIQUE (tenant_id, id),
    CONSTRAINT chk_webserver_site_application_type CHECK (application_type IN ('WEB', 'API')),
    CONSTRAINT chk_webserver_site_type CHECK (site_type BETWEEN 1 AND 6),
    CONSTRAINT chk_webserver_site_status CHECK (status BETWEEN 0 AND 3)
);

COMMENT ON TABLE webserver_site IS 'Web site registry';
COMMENT ON COLUMN webserver_site.id IS 'Snowflake primary key';
COMMENT ON COLUMN webserver_site.uuid IS 'Globally unique identifier';
COMMENT ON COLUMN webserver_site.tenant_id IS 'Tenant ID; 0 = platform-shared data per contract';
COMMENT ON COLUMN webserver_site.organization_id IS 'Organization ID; 0 = tenant-level data';
COMMENT ON COLUMN webserver_site.data_scope IS 'Data scope: 1=tenant, 2=organization, 3=user, 4=platform';
COMMENT ON COLUMN webserver_site.user_id IS 'Owning user ID (nullable)';
COMMENT ON COLUMN webserver_site.name IS 'Site display name';
COMMENT ON COLUMN webserver_site.slug IS 'URL-friendly unique slug within tenant';
COMMENT ON COLUMN webserver_site.application_type IS 'Application traffic category: WEB or API';
COMMENT ON COLUMN webserver_site.site_type IS 'Site type: 1=static, 2=SPA, 3=Node, 4=PHP, 5=Python, 6=other';
COMMENT ON COLUMN webserver_site.status IS 'Status: 0=draft, 1=active, 2=paused, 3=archived';
COMMENT ON COLUMN webserver_site.runtime_config IS 'Runtime configuration JSON';
COMMENT ON COLUMN webserver_site.version IS 'Optimistic concurrency version';

