CREATE TABLE IF NOT EXISTS webserver_domain (
    id              BIGINT       NOT NULL,
    uuid            VARCHAR(64)  NOT NULL,
    tenant_id       BIGINT       NOT NULL DEFAULT 0,
    organization_id BIGINT       NOT NULL DEFAULT 0,
    user_id         BIGINT,
    root_domain_id  BIGINT       NOT NULL,
    hostname        VARCHAR(255) NOT NULL,
    hostname_type   VARCHAR(16)  NOT NULL DEFAULT 'EXACT',
    verification_status VARCHAR(16) NOT NULL DEFAULT 'PENDING',
    verified_at     TIMESTAMPTZ,
    status          INTEGER      NOT NULL DEFAULT 0,
    metadata        JSONB        NOT NULL DEFAULT '{}',
    created_at      TIMESTAMPTZ  NOT NULL,
    updated_at      TIMESTAMPTZ  NOT NULL,
    version         BIGINT       NOT NULL DEFAULT 0,
    deleted_at      TIMESTAMPTZ,
    PRIMARY KEY (id),
    CONSTRAINT uk_webserver_domain_uuid UNIQUE (uuid),
    CONSTRAINT uk_webserver_domain_tenant_id UNIQUE (tenant_id, id),
    CONSTRAINT fk_webserver_domain_root_domain FOREIGN KEY (tenant_id, root_domain_id)
        REFERENCES webserver_root_domain(tenant_id, id),
    CONSTRAINT chk_webserver_domain_hostname_type CHECK (hostname_type IN ('EXACT', 'WILDCARD')),
    CONSTRAINT chk_webserver_domain_verification_status CHECK (
        verification_status IN ('PENDING', 'VERIFIED', 'FAILED', 'EXPIRED')
    ),
    CONSTRAINT chk_webserver_domain_verified_at CHECK (
        (verification_status = 'VERIFIED' AND verified_at IS NOT NULL)
        OR (verification_status <> 'VERIFIED' AND verified_at IS NULL)
    ),
    CONSTRAINT chk_webserver_domain_status CHECK (status BETWEEN 0 AND 2)
);

