    is_primary        BOOLEAN       NOT NULL DEFAULT false,
    redirect_scheme   VARCHAR(8),
    redirect_hostname VARCHAR(253),
    redirect_path_prefix VARCHAR(4096),
    redirect_status_code INTEGER,
    preserve_path     BOOLEAN       NOT NULL DEFAULT true,
    preserve_query    BOOLEAN       NOT NULL DEFAULT true,
    status            VARCHAR(16)   NOT NULL DEFAULT 'PENDING',
    activated_at      TIMESTAMPTZ,
    created_at        TIMESTAMPTZ   NOT NULL,
    updated_at        TIMESTAMPTZ   NOT NULL,
    version           BIGINT        NOT NULL DEFAULT 0,
    deleted_at        TIMESTAMPTZ,
    PRIMARY KEY (id),
    CONSTRAINT uk_webserver_site_binding_uuid UNIQUE (uuid),
    CONSTRAINT uk_webserver_site_binding_tenant_id UNIQUE (tenant_id, id),
    CONSTRAINT fk_webserver_site_binding_site FOREIGN KEY (tenant_id, site_id)
        REFERENCES webserver_site(tenant_id, id),
    CONSTRAINT fk_webserver_site_binding_domain FOREIGN KEY (tenant_id, domain_id)
        REFERENCES webserver_domain(tenant_id, id),
    CONSTRAINT chk_webserver_site_binding_environment CHECK (environment IN ('development', 'test', 'staging', 'production')),
    CONSTRAINT chk_webserver_site_binding_action CHECK (action_type IN ('SERVE', 'REDIRECT')),
    CONSTRAINT chk_webserver_site_binding_status CHECK (status IN ('PENDING', 'ACTIVE', 'PAUSED', 'FAILED', 'ARCHIVED')),
    CONSTRAINT chk_webserver_site_binding_redirect_status CHECK (redirect_status_code IS NULL OR redirect_status_code IN (301, 302, 307, 308)),
    CONSTRAINT chk_webserver_site_binding_redirect CHECK (
        (action_type = 'SERVE' AND redirect_scheme IS NULL AND redirect_hostname IS NULL AND redirect_path_prefix IS NULL AND redirect_status_code IS NULL)
        OR (action_type = 'REDIRECT' AND redirect_status_code IS NOT NULL)
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_webserver_site_binding_active_route
