CREATE TABLE IF NOT EXISTS webserver_tls_policy (
    id                  BIGINT       NOT NULL,
    uuid                VARCHAR(64)  NOT NULL,
    tenant_id           BIGINT       NOT NULL,
    site_binding_id     BIGINT       NOT NULL,
    certificate_source  VARCHAR(16)  NOT NULL DEFAULT 'MANAGED',
    challenge_method    VARCHAR(16)  NOT NULL DEFAULT 'AUTO',
    minimum_tls_version VARCHAR(8)   NOT NULL DEFAULT 'TLS1.2',
    maximum_tls_version VARCHAR(8)   NOT NULL DEFAULT 'TLS1.3',
    alpn_json           JSONB        NOT NULL DEFAULT '["h2","http/1.1"]',
    auto_renew          BOOLEAN      NOT NULL DEFAULT true,
    renew_before_days   INTEGER      NOT NULL DEFAULT 30,
    status              VARCHAR(16)  NOT NULL DEFAULT 'ACTIVE',
    created_at          TIMESTAMPTZ  NOT NULL,
    updated_at          TIMESTAMPTZ  NOT NULL,
    version             BIGINT       NOT NULL DEFAULT 0,
    deleted_at          TIMESTAMPTZ,
    PRIMARY KEY (id),
    CONSTRAINT uk_webserver_tls_policy_uuid UNIQUE (uuid),
    CONSTRAINT fk_webserver_tls_policy_binding FOREIGN KEY (tenant_id, site_binding_id)
        REFERENCES webserver_site_binding(tenant_id, id),
    CONSTRAINT chk_webserver_tls_policy_source CHECK (certificate_source IN ('MANAGED', 'CUSTOM', 'EXTERNAL')),
    CONSTRAINT chk_webserver_tls_policy_challenge CHECK (challenge_method IN ('AUTO', 'HTTP_01', 'DNS_01')),
    CONSTRAINT chk_webserver_tls_policy_versions CHECK (
        minimum_tls_version IN ('TLS1.2', 'TLS1.3')
        AND maximum_tls_version IN ('TLS1.2', 'TLS1.3')
        AND minimum_tls_version <= maximum_tls_version
    ),
    CONSTRAINT chk_webserver_tls_policy_renewal CHECK (renew_before_days BETWEEN 14 AND 90),
    CONSTRAINT chk_webserver_tls_policy_status CHECK (status IN ('ACTIVE', 'PAUSED', 'ARCHIVED'))
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_webserver_tls_policy_active_binding
    ON webserver_tls_policy (site_binding_id)
    WHERE status = 'ACTIVE' AND deleted_at IS NULL;

