    CONSTRAINT chk_webserver_certificate_secret_bundle_payload CHECK (
        OCTET_LENGTH(bundle_encrypted) BETWEEN 64 AND 2097152
    )
);

CREATE TABLE IF NOT EXISTS webserver_certificate_operation (
    id                   BIGINT       NOT NULL,
    uuid                 VARCHAR(64)  NOT NULL,
    tenant_id            BIGINT       NOT NULL,
    certificate_id       BIGINT       NOT NULL,
    requested_by         BIGINT,
    operation_type       VARCHAR(16)  NOT NULL,
    status               VARCHAR(16)  NOT NULL DEFAULT 'PENDING',
    attempt_count        INTEGER      NOT NULL DEFAULT 0,
    max_attempts         INTEGER      NOT NULL DEFAULT 5,
    next_attempt_at      TIMESTAMPTZ  NOT NULL,
    lease_owner          VARCHAR(128),
    lease_expires_at     TIMESTAMPTZ,
    fencing_token        BIGINT       NOT NULL DEFAULT 0,
    failure_code         VARCHAR(64),
    failure_detail       VARCHAR(512),
    idempotency_key_hash VARCHAR(64),
    request_sha256       VARCHAR(64)  NOT NULL,
    created_at           TIMESTAMPTZ  NOT NULL,
    updated_at           TIMESTAMPTZ  NOT NULL,
    completed_at         TIMESTAMPTZ,
    PRIMARY KEY (id),
    CONSTRAINT uk_webserver_certificate_operation_uuid UNIQUE (uuid),
    CONSTRAINT uk_webserver_certificate_operation_tenant_id UNIQUE (tenant_id, id),
    CONSTRAINT fk_webserver_certificate_operation_certificate FOREIGN KEY (tenant_id, certificate_id)
        REFERENCES webserver_certificate(tenant_id, id),
    CONSTRAINT chk_webserver_certificate_operation_type CHECK (operation_type IN ('ISSUE', 'RENEW')),
    CONSTRAINT chk_webserver_certificate_operation_status CHECK (status IN ('PENDING', 'RUNNING', 'SUCCEEDED', 'FAILED')),
    CONSTRAINT chk_webserver_certificate_operation_attempts CHECK (
        max_attempts BETWEEN 1 AND 10
        AND attempt_count BETWEEN 0 AND max_attempts
    ),
    CONSTRAINT chk_webserver_certificate_operation_fencing CHECK (fencing_token >= 0),
    CONSTRAINT chk_webserver_certificate_operation_hashes CHECK (
        request_sha256 ~ '^[0-9a-f]{64}$'
        AND (idempotency_key_hash IS NULL OR idempotency_key_hash ~ '^[0-9a-f]{64}$')
    ),
    CONSTRAINT chk_webserver_certificate_operation_lease CHECK (
        (status = 'RUNNING' AND lease_owner IS NOT NULL AND lease_expires_at IS NOT NULL)
        OR (status <> 'RUNNING' AND lease_owner IS NULL AND lease_expires_at IS NULL)
    ),
    -- A diagnostic without a code would be a ghost failure: the console keys its
    -- copy off the code, so the pair is only meaningful together.
    CONSTRAINT chk_webserver_certificate_operation_failure_detail CHECK (
        failure_detail IS NULL OR failure_code IS NOT NULL
    ),
    CONSTRAINT chk_webserver_certificate_operation_completion CHECK (
        (status IN ('SUCCEEDED', 'FAILED') AND completed_at IS NOT NULL)
        OR (status IN ('PENDING', 'RUNNING') AND completed_at IS NULL)
    )
);

COMMENT ON TABLE webserver_certificate_operation IS 'Durable certificate issuance and renewal operation with lease fencing and bounded retry';
COMMENT ON COLUMN webserver_certificate_operation.idempotency_key_hash IS 'SHA-256 of the tenant, actor, operation scope, and raw Idempotency-Key; raw keys are never stored';
COMMENT ON COLUMN webserver_certificate_operation.request_sha256 IS 'Canonical request fingerprint used to reject conflicting idempotency-key replay';
COMMENT ON COLUMN webserver_certificate_operation.failure_detail IS 'What the failure actually said: the provider's own diagnostic, redacted and bounded, so an operator can act on it without reading the server log';

CREATE UNIQUE INDEX IF NOT EXISTS uk_webserver_certificate_operation_idempotency
    ON webserver_certificate_operation (tenant_id, idempotency_key_hash)
    WHERE idempotency_key_hash IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uk_webserver_certificate_operation_active_certificate
    ON webserver_certificate_operation (tenant_id, certificate_id)
    WHERE status IN ('PENDING', 'RUNNING');

CREATE INDEX IF NOT EXISTS idx_webserver_certificate_operation_claim
    ON webserver_certificate_operation (next_attempt_at, id)
    WHERE status IN ('PENDING', 'RUNNING');

CREATE INDEX IF NOT EXISTS idx_webserver_certificate_operation_certificate_history
    ON webserver_certificate_operation (tenant_id, certificate_id, created_at DESC, id DESC);

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_webserver_certificate_current_version') THEN
        ALTER TABLE webserver_certificate ADD CONSTRAINT fk_webserver_certificate_current_version FOREIGN KEY (id, current_version_id) REFERENCES webserver_certificate_version(certificate_id, id);
    END IF;
END $$;

CREATE TABLE IF NOT EXISTS webserver_listener_certificate_binding (
    id                     BIGINT      NOT NULL,
    uuid                   VARCHAR(64) NOT NULL,
    tenant_id              BIGINT      NOT NULL,
    site_binding_id        BIGINT      NOT NULL,
    certificate_id         BIGINT      NOT NULL,
    desired_version_id     BIGINT      NOT NULL,
    current_version_id     BIGINT,
    key_algorithm          VARCHAR(16) NOT NULL,
    priority               INTEGER     NOT NULL DEFAULT 100,
    is_default             BOOLEAN     NOT NULL DEFAULT false,
    status                 VARCHAR(16) NOT NULL DEFAULT 'PENDING',
    activated_at           TIMESTAMPTZ,
    created_at             TIMESTAMPTZ NOT NULL,
    updated_at             TIMESTAMPTZ NOT NULL,
    version                BIGINT      NOT NULL DEFAULT 0,
    deleted_at             TIMESTAMPTZ,
    PRIMARY KEY (id),
    CONSTRAINT uk_webserver_listener_certificate_binding_uuid UNIQUE (uuid),
    CONSTRAINT uk_webserver_listener_certificate_binding_certificate UNIQUE (site_binding_id, certificate_id),
    CONSTRAINT fk_webserver_listener_certificate_binding_route FOREIGN KEY (tenant_id, site_binding_id)
        REFERENCES webserver_site_binding(tenant_id, id),
    CONSTRAINT fk_webserver_listener_certificate_binding_certificate FOREIGN KEY (tenant_id, certificate_id)
        REFERENCES webserver_certificate(tenant_id, id),
    CONSTRAINT fk_webserver_listener_certificate_binding_desired_version FOREIGN KEY (certificate_id, desired_version_id)
        REFERENCES webserver_certificate_version(certificate_id, id),
    CONSTRAINT fk_webserver_listener_certificate_binding_current_version FOREIGN KEY (certificate_id, current_version_id)
        REFERENCES webserver_certificate_version(certificate_id, id),
    CONSTRAINT chk_webserver_listener_certificate_binding_algorithm CHECK (key_algorithm IN ('RSA', 'ECDSA')),
    CONSTRAINT chk_webserver_listener_certificate_binding_priority CHECK (priority BETWEEN 0 AND 10000),
    CONSTRAINT chk_webserver_listener_certificate_binding_status CHECK (status IN ('PENDING', 'DEPLOYING', 'ACTIVE', 'PAUSED', 'FAILED', 'ARCHIVED')),
    CONSTRAINT chk_webserver_listener_certificate_binding_active_version CHECK (
        status <> 'ACTIVE'
        OR (
            current_version_id = desired_version_id
            AND activated_at IS NOT NULL
        )
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_webserver_listener_certificate_binding_active_algorithm
    ON webserver_listener_certificate_binding (site_binding_id, key_algorithm)
    WHERE status <> 'ARCHIVED' AND deleted_at IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uk_webserver_listener_certificate_binding_default
    ON webserver_listener_certificate_binding (site_binding_id)
    WHERE is_default = true AND status <> 'ARCHIVED' AND deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_webserver_listener_certificate_binding_certificate
    ON webserver_listener_certificate_binding (tenant_id, certificate_id, status)
    WHERE deleted_at IS NULL;

-- List-query hardening: listener binding listing orders by
-- (is_default DESC, priority ASC, id ASC) per site binding.
CREATE INDEX IF NOT EXISTS idx_webserver_listener_certificate_binding_site_sort
    ON webserver_listener_certificate_binding (site_binding_id, is_default, priority, id)
    WHERE deleted_at IS NULL;

CREATE TABLE IF NOT EXISTS webserver_source_version (
    id              BIGINT       NOT NULL,
    uuid            VARCHAR(64)  NOT NULL,
    tenant_id       BIGINT       NOT NULL,
    organization_id BIGINT       NOT NULL DEFAULT 0,
    user_id         BIGINT,
    site_id         BIGINT       NOT NULL,
    version_tag     VARCHAR(100) NOT NULL,
    source_type     VARCHAR(16)  NOT NULL,
    source_ref      VARCHAR(500),
    commit_hash     VARCHAR(64),
    artifact_path   VARCHAR(500) NOT NULL,
    artifact_size   BIGINT       NOT NULL,
    artifact_hash   VARCHAR(64)  NOT NULL,
    config_snapshot JSONB        NOT NULL DEFAULT '{}',
    status          INTEGER      NOT NULL DEFAULT 1,
    pruned_at       TIMESTAMPTZ,
    pruned_by       BIGINT,
    metadata        JSONB        NOT NULL DEFAULT '{}',
    created_at      TIMESTAMPTZ  NOT NULL,
    updated_at      TIMESTAMPTZ  NOT NULL,
    version         BIGINT       NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
