    CONSTRAINT fk_webserver_source_version_site FOREIGN KEY (site_id) REFERENCES webserver_site(id)
);

COMMENT ON TABLE webserver_source_version IS 'Immutable Drive-backed application source version';
COMMENT ON COLUMN webserver_source_version.status IS 'Status: 0=preparing, 1=ready, 2=failed, 3=pruned';

CREATE INDEX IF NOT EXISTS idx_webserver_source_version_site_created
    ON webserver_source_version (site_id, created_at DESC);

-- List-query hardening: source-version listing filters by tenant then site and
-- sorts by created_at DESC (PAGINATION_SPEC/DATABASE_SPEC §20.5).
CREATE INDEX IF NOT EXISTS idx_webserver_source_version_tenant_site_created
    ON webserver_source_version (tenant_id, site_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_webserver_source_version_retention
    ON webserver_source_version (tenant_id, site_id, status, created_at DESC);

