    CONSTRAINT uk_webserver_runtime_assignment_tenant_id
        UNIQUE (tenant_id, id, server_id),
    CONSTRAINT uk_webserver_runtime_assignment_generation
        UNIQUE (tenant_id, server_id, environment, generation),
    CONSTRAINT uk_webserver_runtime_assignment_snapshot UNIQUE (snapshot_uuid),
