-- Older baselines declared uk_webserver_site_slug as a table constraint, which
-- PostgreSQL only allows removing via DROP CONSTRAINT; handle both shapes.
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conrelid = 'webserver_site'::regclass
          AND conname = 'uk_webserver_site_slug'
    ) THEN
        ALTER TABLE webserver_site DROP CONSTRAINT uk_webserver_site_slug;
    ELSE
        DROP INDEX IF EXISTS uk_webserver_site_slug;
    END IF;
END
$$;
CREATE UNIQUE INDEX IF NOT EXISTS uk_webserver_site_slug
    ON webserver_site (tenant_id, slug)
    WHERE deleted_at IS NULL;

-- Tenant-scoped Nginx config listing order.
CREATE INDEX IF NOT EXISTS idx_webserver_nginx_config_tenant_updated
    ON webserver_nginx_config (tenant_id, updated_at DESC, id DESC);

-- Tenant-scoped audit log listing order.
CREATE INDEX IF NOT EXISTS idx_webserver_audit_log_tenant_created
    ON webserver_audit_log (tenant_id, created_at DESC, id DESC);

-- Web Node credential (metadata agentTokenHash) lookups. The GIN index
-- serves JSONB containment queries such as
-- `metadata @> '{"agentTokenHash": ...}'`; extraction predicates
-- (`metadata ->> 'agentTokenHash' = ...`) cannot use this index and must not
-- be reintroduced on the authentication/heartbeat path.
CREATE INDEX IF NOT EXISTS idx_webserver_server_metadata_gin
    ON webserver_server USING GIN (metadata);

-- Environment variables belong to a site. The folded baseline already carries
-- this constraint on fresh installs, so add it only when it is still missing.
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint
        WHERE conrelid = 'webserver_env_variable'::regclass
          AND conname = 'fk_webserver_env_variable_site'
    ) THEN
        ALTER TABLE webserver_env_variable
            ADD CONSTRAINT fk_webserver_env_variable_site
            FOREIGN KEY (site_id) REFERENCES webserver_site(id);
    END IF;
END
$$;

