    operation_type       VARCHAR(16)  NOT NULL,
    status               VARCHAR(16)  NOT NULL DEFAULT 'PENDING',
    attempt_count        INTEGER      NOT NULL DEFAULT 0,
    max_attempts         INTEGER      NOT NULL DEFAULT 5,
    next_attempt_at      TIMESTAMPTZ  NOT NULL,
    lease_owner          VARCHAR(128),
    lease_expires_at     TIMESTAMPTZ,
    fencing_token        BIGINT       NOT NULL DEFAULT 0,
    failure_code         VARCHAR(64),
    failure_detail       VARCHAR(512),
    idempotency_key_hash VARCHAR(64),
    request_sha256       VARCHAR(64)  NOT NULL,
    created_at           TIMESTAMPTZ  NOT NULL,
    updated_at           TIMESTAMPTZ  NOT NULL,
    completed_at         TIMESTAMPTZ,
    PRIMARY KEY (id),
    CONSTRAINT uk_webserver_certificate_operation_uuid UNIQUE (uuid),
    CONSTRAINT uk_webserver_certificate_operation_tenant_id UNIQUE (tenant_id, id),
    CONSTRAINT fk_webserver_certificate_operation_certificate FOREIGN KEY (tenant_id, certificate_id)
        REFERENCES webserver_certificate(tenant_id, id),
    CONSTRAINT chk_webserver_certificate_operation_type CHECK (operation_type IN ('ISSUE', 'RENEW')),
    CONSTRAINT chk_webserver_certificate_operation_status CHECK (status IN ('PENDING', 'RUNNING', 'SUCCEEDED', 'FAILED')),
    CONSTRAINT chk_webserver_certificate_operation_attempts CHECK (
        max_attempts BETWEEN 1 AND 10
        AND attempt_count BETWEEN 0 AND max_attempts
    ),
    CONSTRAINT chk_webserver_certificate_operation_fencing CHECK (fencing_token >= 0),
    CONSTRAINT chk_webserver_certificate_operation_hashes CHECK (
        request_sha256 ~ '^[0-9a-f]{64}$'
